-- PixelRP: Cheapyxony's furni, in Builders > Designer > Haaziq.
--
-- 309 pieces hung under the EXISTING Haaziq designer page, beside the
-- Cheapyxo House set already there. Generated by
-- docker/nitro/import-pack-tree.py.
--
-- A separate page rather than an addition to Cheapyxo House, because it is not
-- the same export: the 149 already on that page are all Haaziq_*, and this is
-- two other lines - 269 Habblet_haaziq_* and 40 city_haaziq_* / city_nino_*.
-- All 309 were checked against all 149 by the hash of their spritesheet and
-- not one is a repeat, so nothing here duplicates what we had.
--
-- The pack's manifests carry no names - each item's `name` is its classname -
-- so the titles are derived from those and the numbered line reads 'Habblet
-- Haaziq 07'. The city_* line at least says what it is, in French: 'City
-- Haaziq Arbre', 'City Nino Assiettes'. That is what the download contains;
-- inventing nicer ones would be inventing, not importing.
--
-- The rendering half is the .nitro bundles, the icons and the FurnitureData
-- entries under nitro/overrides/; the rows below are inert without them.
--
-- Everything is free - the catalog has been since 90_FreeCatalog.
--
-- Idempotent: fixed id ranges, cleared before insert. The pages under Haaziq are
-- renumbered alphabetically at the end, which lands the same way every run.

SET @builders := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1),
    912362);
SET @designer := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 941000 LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `caption` IN ('Designer Furni', 'Designer')
        AND `parent_id` = @builders ORDER BY `id` LIMIT 1));
SET @haaziq := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 942036 LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `caption` = 'Haaziq' AND `parent_id` = @designer
        ORDER BY `id` LIMIT 1));

DELETE FROM `catalog_items` WHERE `item_id` BETWEEN 110000 AND 110308;
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 948000 AND 948999;
DELETE FROM `furniture` WHERE `id` BETWEEN 110000 AND 110308;

     `page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
VALUES
    (948000, @haaziq, 'Cheapyxony', 193, 2, 0, 1, '', 'default_3x3', '', '', b'1', b'1');


-- Furniture. id == sprite_id, the convention every custom line here follows;
-- interaction_modes_count is the bundle's own animation count.


SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @haaziq
    ORDER BY `caption`;
